public JCMethodDecl generateDefaultProvider(Name methodName, JavacNode fieldNode, List<JCTypeParameter> params, JavacNode source) {
	if (fieldNode.getKind() != Kind.FIELD) return null;

	JavacAST ast = fieldNode.getAst();
	JavacTreeMaker maker = ast.getTreeMaker();
	JCVariableDecl field = (JCVariableDecl) fieldNode.get();

	JavacNode enclosingType = fieldNode.up();
	JCClassDecl classDecl = (JCClassDecl) enclosingType.get();
	List<JCTypeParameter> typeParams = classDecl.typarams;
	if (params != null && params != typeParams) typeParams = params;

	// Lombok tries to keep the position of the original initializer. First we save the expression ...
	JCExpression init = field.init;
	JCExpression fieldType = field.vartype;
	field.init = null;

	// ... then we generate an empty return statement ...
	JCReturn statement = maker.Return(null);
	JCBlock body = maker.Block(this.defaultProviderBodyFlags, List.<JCStatement>of(statement));
	int modifiers = this.defaultProviderModifiers;
	JCMethodDecl defaultProvider = maker.MethodDef(maker.Modifiers(modifiers), methodName, cloneType(maker, fieldType, fieldNode), copyTypeParams(fieldNode, typeParams), List.<JCVariableDecl>nil(), List.<JCExpression>nil(), body, null);
	// ... then we set positions for everything else ...
	recursiveSetGeneratedBy(defaultProvider, source);
	// ... and finally add back the original expression
	statement.expr = init;
	return defaultProvider;
}

