docker exec cli-eval-opencode-projectlombok__lombok-3052-e7d958b5 sh -lc 'mkdir -p /tmp/repro && cat > /tmp/repro/MyTest.java <<EOF
import lombok.Builder;
import lombok.Value;

@Builder
public class MyTest {

    @Builder.Default
    String foo = doSth(MyClass.myInt(), MyClass.myChar());

    @Value
    static class MyClass<T> {
        T value;
        static MyClass<Integer> myInt() {
            return new MyClass<>(42);
        }
        static MyClass<Character> myChar() {
            return new MyClass<>(Character.valueOf((char) 65));
        }
    }

    static String doSth(MyClass<Integer> i, MyClass<Character> c) {
        return i.value.toString() + c.value.toString();
    }

    public static void main(String... args) {
        MyTest test = MyTest.builder().build();
        System.out.println(test.foo);
    }

}
EOF
cd /tmp/repro && javac -cp /testbed/dist/lombok.jar MyTest.java && java -cp .:/testbed/dist/lombok.jar MyTest'

